python3 -c "
import json,collections
plan=json.load(open('data/trade_plans/plan_[REDACTED]_[REDACTED].json'))
plan_tickers={o['ticker'] for o in plan['orders']}
# latest fillQuantity per order id, filtered to plan tickers
latest={}
for line in open('[REDACTED]'):
    try: r=json.loads(line)
    except: continue
    seen=[]
    k=r.get('kind')
    if k=='orders': seen=r.get('payload',{}).get('orders') or []
    elif k=='place_order':
        rr=r.get('payload',{}).get('resp') or {}
        if rr.get('id') is not None: seen=[rr]
    for o in seen:
        if o.get('id') is not None and o.get('symbol') in plan_tickers:
            latest[o['id']]=o
real=collections.Counter()
norders=collections.Counter()
for o in latest.values():
    fq=o.get('fillQuantity') or 0
    if fq>0:
        real[o['symbol']]+=fq
        norders[o['symbol']]+=1
print('distinct order ids (plan tickers):',len(latest))
for s in sorted(real, key=lambda x:-real[x]):
    print(f'{s}: real={real[s]}  #orders={norders[s]}')
